\coordinate (b2) at (0,4,3);
\coordinate (b3) at (0,1,3);
\coordinate (f0) at (5,0,0);
\coordinate (f1) at (5,5,0);
\coordinate (f2) at (5,4,3);
\coordinate (f3) at (5,1,3);
\draw (b1)--(b0)--(b3);
\draw[dashed] (b0)--(f0);
\draw (b1)--(b2)--(b3);
\draw[dashed] (f0)--(f1);
\draw (f1)--(f2)--(f3);
\draw[dashed] (f3)--(f0);
\draw (b2)--(f2);
\draw (b3)--(f3);
\draw (b1)--(f1) node[midway,below right,fill=white,inner sep=1pt] {$h$};
\draw[-{Stealth}] (5,-1.6,4.4)--(5,1.8,1.6);
\node[above left] at (5,-1.6,4.4) {$A$};
\end{tikzpicture}
[/tikz]

